def game_bj_action_surrender(db, game_id, player_id):
    game = db_query('SELECT * FROM blackjack_games WHERE id = ? AND player_id = ? AND status = ?', (game_id, player_id, 'active')).fetchone()
    if not game:
        raise GameNotFound()
    cards = json.loads(game['player_cards_json'])
    if len(cards) != 2:
        raise InvalidAction('surrender_only_on_first_two_cards')
    if game['split_count'] > 0:
        raise InvalidAction('cannot_surrender_after_split')
    dealer_cards = json.loads(game['dealer_cards_json'])
    dealer_up_value = card_value_high(dealer_cards[0])
    if dealer_up_value not in (9, 10, 11):
        raise InvalidAction('late_surrender_only_vs_dealer_9_10_or_A')
    refund = game['bet'] // 2
    _add_points(db, player_id, refund, label=f'blackjack_surrender_game_{game_id}')
    db_execute('UPDATE blackjack_games SET status = ?, surrender_amount = ?, result_json = ? WHERE id = ?', ('done_surrender', refund, json.dumps({'outcome': 'surrender', 'refund_pts': refund}), game_id))
    emit_animation_event('blackjack_surrender_animation', {'refund_pts': refund})
    return {'surrendered': True, 'refund_pts': refund}
